import tempfile
import torch
import torch.nn as nn
from topologies import Trainer, build, synth
root = tempfile.mkdtemp()
@synth.generator
def samples(ctx):
    features = torch.randn(4, generator=ctx.rng.torch)
    index = int(ctx.index) % 3
    if index == 0:
        survival = torch.tensor([0.0, 0.0])
        event = torch.tensor([1.0, 0.0])
    elif index == 1:
        survival = torch.tensor([1.0, 0.0])
        event = torch.tensor([0.0, 1.0])
    else:
        survival = torch.tensor([1.0, 0.0])
        event = torch.tensor([0.0, 0.0])
    return {"inputs": synth.Tensor(features), "packed": synth.Tensor(torch.cat((survival, event)))}
ds = synth.Spec("nnet-survival", generator=samples, size=12, splits={"train": 1.0}, seed=7, root=root, monitor="none").run()
train = ds.for_recipe("structured-objective", split="train")
class SurvivalModel(nn.Module):
    def __init__(self):
        super().__init__()
        self.network = build("mlp", "tiny", in_features=4, out_features=2)
    def forward(self, inputs):
        return {"logits": self.network(inputs)}
model = SurvivalModel()
trainer = Trainer(model, train, recipe="structured-objective", recipe_config={"loss": "nnet-survival", "loss_kwargs": {"from_logits": True}, "bindings": {"logits_or_prediction": {"output": "logits"}, "targets": {"batch": "packed"}}}, batch_size=4, max_epochs=1, device="cpu")
trainer.fit()
